class Person:
    def __init__(self, name: str, age: int) -> None:
        self.name = name
        self.age = age
    '''
    方法: 吃东西
    food_name: 食物名字
    '''
    def eat(self, food_name: str):
        print(f"{self.name}, {self.age}岁, 吃{food_name}")


